select json_build_object('active_meat',(select count(*) from raw_items where section='meat' and merged_into is null and not hidden),'merged',(select count(*) from raw_items where merged_into is not null),'by_cat',(select json_agg(x) from (select coalesce(nutrient,'(none)') c,count(*) n from raw_items where section='meat' and merged_into is null and not hidden group by 1 order by 2 desc) x),'nocat',(select json_agg(name) from raw_items where section='meat' and merged_into is null and not hidden and coalesce(nutrient,'')=''),'dangling',(select count(*) from raw_week_items i join raw_items r on r.id=i.item_id where r.merged_into is not null)) r;
